import{_ as e,o as a,c as r,ae as o}from"./chunks/framework.BX_mlWST.js";const g=JSON.parse('{"title":"Farm Co","description":"","frontmatter":{"title":"Farm Co","prev":{"text":"Shops","link":"/Main/Main/GeneralKnowledge/Shops&Landmarks/Shops/shops"}},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Shops&Landmarks/Shops/farmco.md","filePath":"Main/Main/GeneralKnowledge/Shops&Landmarks/Shops/farmco.md"}'),d={name:"Main/Main/GeneralKnowledge/Shops&Landmarks/Shops/farmco.md"};function s(l,t,i,n,h,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<hr><h1 id="farmco" tabindex="-1">FarmCo <a class="header-anchor" href="#farmco" aria-label="Permalink to &quot;FarmCo&quot;">​</a></h1><p><strong>FarmCo</strong> is a shop in <strong>Farming And Friends</strong> where players can purchase crop seeds and crop pallets.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>🍇 Grape Seed Boxes: Unlike the other crop boxes sold by FarmCo, Grape Seed Boxes contain only 10 seeds per box. All other crop boxes contain 50 seeds per box.</p></div><h2 id="crop-box-prices" tabindex="-1">Crop Box Prices <a class="header-anchor" href="#crop-box-prices" aria-label="Permalink to &quot;Crop Box Prices&quot;">​</a></h2><p>FarmCo sells individual crop boxes containing seeds for different crops.</p><table tabindex="0"><thead><tr><th>Crop</th><th style="text-align:right;">Price</th></tr></thead><tbody><tr><td>🌾 Wheat Seeds</td><td style="text-align:right;">$100</td></tr><tr><td>🌽 Corn Seeds</td><td style="text-align:right;">$250</td></tr><tr><td>🌾 Rice Seeds</td><td style="text-align:right;">$2,000</td></tr><tr><td>🌾 Oat Seeds</td><td style="text-align:right;">$2,200</td></tr><tr><td>🎋 Sugarcane Seeds</td><td style="text-align:right;">$8,400</td></tr><tr><td>🫘 Soybean Seeds</td><td style="text-align:right;">$24,000</td></tr><tr><td>🍅 Tomato Seeds</td><td style="text-align:right;">$26,400</td></tr><tr><td>🥬 Cabbage Seeds</td><td style="text-align:right;">$57,600</td></tr><tr><td>🥕 Carrot Seeds</td><td style="text-align:right;">$85,000</td></tr><tr><td>🍇 Grape Seeds</td><td style="text-align:right;">$105,000</td></tr><tr><td>🥔 Potato Seeds</td><td style="text-align:right;">$120,000</td></tr></tbody></table><h2 id="pallet-prices" tabindex="-1">Pallet Prices <a class="header-anchor" href="#pallet-prices" aria-label="Permalink to &quot;Pallet Prices&quot;">​</a></h2><p>FarmCo also sells crop pallets containing multiple crop boxes.</p><table tabindex="0"><thead><tr><th>Crop</th><th style="text-align:right;">Pallet Price</th></tr></thead><tbody><tr><td>🌾 Wheat</td><td style="text-align:right;">$2,565</td></tr><tr><td>🌽 Corn</td><td style="text-align:right;">$6,412</td></tr><tr><td>🌾 Rice</td><td style="text-align:right;">$51,300</td></tr><tr><td>🌾 Oat</td><td style="text-align:right;">$56,430</td></tr><tr><td>🎋 Sugarcane</td><td style="text-align:right;">$113,719</td></tr><tr><td>🫘 Soybean</td><td style="text-align:right;">$615,600</td></tr><tr><td>🍅 Tomato</td><td style="text-align:right;">$677,160</td></tr><tr><td>🥬 Cabbage</td><td style="text-align:right;">$1,477,440</td></tr><tr><td>🥕 Carrot</td><td style="text-align:right;">$2,180,250</td></tr><tr><td>🍇 Grape Seeds</td><td style="text-align:right;">$2,693,250</td></tr><tr><td>🥔 Potato</td><td style="text-align:right;">$3,078,000</td></tr></tbody></table><h2 id="pallet-information" tabindex="-1">Pallet Information <a class="header-anchor" href="#pallet-information" aria-label="Permalink to &quot;Pallet Information&quot;">​</a></h2><ul><li>Each pallet contains <strong>27 crop boxes</strong>.</li><li>Pallets are sold at approximately a <strong>5% discount</strong> compared to purchasing 27 individual crop boxes.</li><li>A <strong>forklift</strong> is required to move the pallets.</li></ul><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><h3 id="crop-boxes" tabindex="-1">Crop Boxes <a class="header-anchor" href="#crop-boxes" aria-label="Permalink to &quot;Crop Boxes&quot;">​</a></h3><p><img src="https://media.discordapp.net/attachments/1479332298049716267/1480388281756680335/Screenshot_2026-03-06_101538.png?format=webp&amp;quality=lossless&amp;width=640&amp;height=237" alt="FarmCo Crop Boxes"></p><h3 id="crop-pallets" tabindex="-1">Crop Pallets <a class="header-anchor" href="#crop-pallets" aria-label="Permalink to &quot;Crop Pallets&quot;">​</a></h3><p><img src="https://media.discordapp.net/attachments/1479332298049716267/1480388300048044153/Screenshot_2026-03-06_105732.png?format=webp&amp;quality=lossless&amp;width=640&amp;height=258" alt="FarmCo Crop Pallets"></p><blockquote><p><strong>Note:</strong> Prices shown on this page are based on the information currently documented and may change with future game updates.</p></blockquote>',18)])])}const m=e(d,[["render",s]]);export{g as __pageData,m as default};
